def row(i, check, loc, status, ev, fix=None, sev=None):
    d = {"id": i, "check": check, "location": loc, "status": status, "evidence": ev}
    if status != "PASS":
        d["fix"] = fix
        d["severity"] = sev or "LOW"
    return d

